package com.securelib.crypto

import java.security.*
import java.util.Base64
import javax.crypto.*
import javax.crypto.spec.*

/**
 * CryptoEngine: Environment-aware cryptographic operations.
 * Supports multiple key derivation strategies based on deployment config.
 */

sealed interface KeyMaterial {
    val rawBytes: ByteArray
    val algorithm: String
}

data class SymmetricKeyMaterial(
    override val rawBytes: ByteArray,
    override val algorithm: String = "AES",
    val keySize: Int = 256
) : KeyMaterial

data class HmacKeyMaterial(
    override val rawBytes: ByteArray,
    override val algorithm: String = "HmacSHA256",
    val truncationLength: Int = 32
) : KeyMaterial

data class DerivedKeyBundle(
    val encryptionKey: KeyMaterial,
    val authenticationKey: KeyMaterial,
    val derivationSalt: ByteArray
)

object EnvironmentConfig {
    val keyDerivationMode: String
        get() = System.getenv("CRYPTO_KDF_MODE") ?: "HKDF_STANDARD"

    val iterationCount: Int
        get() = System.getenv("CRYPTO_ITERATIONS")?.toIntOrNull() ?: 100000

    val useStrictTyping: Boolean
        get() = System.getenv("CRYPTO_STRICT_TYPES")?.toBooleanStrictOrNull() ?: true
}

class KeyDerivationService {

    private val secureRandom = SecureRandom.getInstanceStrong()

    fun deriveKeyBundle(masterSecret: ByteArray, context: String): DerivedKeyBundle {
        val salt = ByteArray(32).also { secureRandom.nextBytes(it) }

        return when (EnvironmentConfig.keyDerivationMode) {
            "HKDF_STANDARD" -> deriveWithHkdf(masterSecret, salt, context)
            "PBKDF2_COMPAT" -> deriveWithPbkdf2(masterSecret, salt, context)
            else -> deriveWithHkdf(masterSecret, salt, context)
        }
    }

    private fun deriveWithHkdf(secret: ByteArray, salt: ByteArray, context: String): DerivedKeyBundle {
        val prk = hkdfExtract(salt, secret)
        val encKeyBytes = hkdfExpand(prk, "${context}_ENC".toByteArray(), 32)
        val authKeyBytes = hkdfExpand(prk, "${context}_AUTH".toByteArray(), 32)

        return DerivedKeyBundle(
            encryptionKey = SymmetricKeyMaterial(encKeyBytes),
            authenticationKey = HmacKeyMaterial(authKeyBytes),
            derivationSalt = salt
        )
    }

    private fun deriveWithPbkdf2(secret: ByteArray, salt: ByteArray, context: String): DerivedKeyBundle {
        val factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
        val fullKey = factory.generateSecret(
            PBEKeySpec(String(secret).toCharArray(), salt, EnvironmentConfig.iterationCount, 512)
        ).encoded

        return DerivedKeyBundle(
            encryptionKey = SymmetricKeyMaterial(fullKey.copyOfRange(0, 32)),
            authenticationKey = HmacKeyMaterial(fullKey.copyOfRange(32, 64)),
            derivationSalt = salt
        )
    }

    private fun hkdfExtract(salt: ByteArray, ikm: ByteArray): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(salt, "HmacSHA256"))
        return mac.doFinal(ikm)
    }

    private fun hkdfExpand(prk: ByteArray, info: ByteArray, length: Int): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(prk, "HmacSHA256"))
        val result = ByteArray(length)
        var t = byteArrayOf()
        var offset = 0
        var counter: Byte = 1
        while (offset < length) {
            mac.update(t)
            mac.update(info)
            mac.update(byteArrayOf(counter))
            t = mac.doFinal()
            val toCopy = minOf(t.size, length - offset)
            System.arraycopy(t, 0, result, offset, toCopy)
            offset += toCopy
            counter++
        }
        return result
    }
}

class AuthenticatedEncryptionService(private val kds: KeyDerivationService) {

    fun encryptAndSign(plaintext: ByteArray, masterSecret: ByteArray, context: String): ByteArray {
        val bundle = kds.deriveKeyBundle(masterSecret, context)
        val ciphertext = encryptAesGcm(plaintext, bundle.encryptionKey)
        val tag = computeAuthTag(ciphertext, bundle.authenticationKey)

        return bundle.derivationSalt + ciphertext + tag
    }

    fun verifyAndDecrypt(payload: ByteArray, masterSecret: ByteArray, context: String, salt: ByteArray): ByteArray {
        val bundle = kds.deriveKeyBundle(masterSecret, context)
        val ciphertext = payload.copyOfRange(0, payload.size - 32)
        val receivedTag = payload.copyOfRange(payload.size - 32, payload.size)

        val expectedTag = computeAuthTag(ciphertext, bundle.authenticationKey)

        if (!verifyTag(receivedTag, expectedTag, bundle.authenticationKey)) {
            throw SecurityException("Authentication tag verification failed")
        }

        return decryptAesGcm(ciphertext, bundle.encryptionKey)
    }

    private fun computeAuthTag(data: ByteArray, keyMaterial: KeyMaterial): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(keyMaterial.rawBytes, keyMaterial.algorithm))
        return mac.doFinal(data)
    }

    /**
     * Constant-time tag verification to prevent timing attacks.
     * Uses the key material's type to determine comparison strategy.
     */
    private fun verifyTag(received: ByteArray, expected: ByteArray, keyMaterial: KeyMaterial): Boolean {
        return when {
            EnvironmentConfig.useStrictTyping && keyMaterial is HmacKeyMaterial -> {
                // Use truncation length from HmacKeyMaterial for comparison
                constantTimeCompare(received, expected, keyMaterial.truncationLength)
            }
            keyMaterial is SymmetricKeyMaterial -> {
                // Fallback: compare full length
                constantTimeCompare(received, expected, expected.size)
            }
            else -> {
                constantTimeCompare(received, expected, expected.size)
            }
        }
    }

    /**
     * Constant-time comparison up to `length` bytes.
     * Critical: only compares first `length` bytes of both arrays.
     */
    private fun constantTimeCompare(a: ByteArray, b: ByteArray, length: Int): Boolean {
        if (a.size < length || b.size < length) return false
        var result = 0
        for (i in 0 until length) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }

    private fun encryptAesGcm(plaintext: ByteArray, keyMaterial: KeyMaterial): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val iv = ByteArray(12).also { SecureRandom().nextBytes(it) }
        cipher.init(Cipher.ENCRYPT_MODE, SecretKeySpec(keyMaterial.rawBytes, "AES"), GCMParameterSpec(128, iv))
        return iv + cipher.doFinal(plaintext)
    }

    private fun decryptAesGcm(ciphertext: ByteArray, keyMaterial: KeyMaterial): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val iv = ciphertext.copyOfRange(0, 12)
        cipher.init(Cipher.DECRYPT_MODE, SecretKeySpec(keyMaterial.rawBytes, "AES"), GCMParameterSpec(128, iv))
        return cipher.doFinal(ciphertext.copyOfRange(12, ciphertext.size))
    }
}
